le`,`content`) values (\"0\",\"2024-09-25 16:00:00\",\"3.0\",\"国庆假期运营指南\",\"国庆假期临近，预计出行需求大增，平台将发布假期热门区域预测，助您提升接单效率，祝您节日快乐！\");\n\nCREATE TABLE IF NOT EXISTS `28836204`.`message_type_enum` (\n`message_type_enum_id` INT AUTO_INCREMENT  COMMENT '主键',\n`type_name` varchar(512) NOT NULL  COMMENT '类型名称',\nPRIMARY KEY (`message_type_enum_id`)\n) COMMENT='消息类型';\nINSERT INTO `28836204`.`message_type_enum` (`type_name`) values (\"系统公告\");\nINSERT INTO `28836204`.`message_type_enum` (`type_name`) values (\"平台通知\");\nINSERT INTO `28836204`.`message_type_enum` (`type_name`) values (\"活动提醒\");\n\nCREATE TABLE IF NOT EXISTS `28836204`.`wallet` (\n`wallet_id` INT AUTO_INCREMENT  COMMENT '主键',\n`user_info_user_info_id_1` INT NOT NULL  COMMENT '用户ID',\n`balance` DECIMAL(10,2) NOT NULL  COMMENT '余额',\n`member_type_enum_member_type_enum_id_1` INT NOT NULL  COMMENT '会员类型',\n`member_expire` DATE DEFAULT (CURRENT_DATE)  COMMENT '会员到期',\nPRIMARY KEY (`wallet_id`)\n) COMMENT='钱包';\nINSERT INTO `28836204`.`wallet` (`user_info_user_info_id_1`,`balance`,`member_expire`,`member_type_enum_member_type_enum_id_1`) values (\"1.0\",\"100.5\",\"2026-05-26 10:44:57\",\"2.0\");\nINSERT INTO `28836204`.`wallet` (`user_info_user_info_id_1`,`balance`,`member_expire`,`member_type_enum_member_type_enum_id_1`) values (\"2.0\",\"50.0\",\"2026-05-26 10:44:57\",\"1.0\");\nINSERT INTO `28836204`.`wallet` (`user_info_user_info_id_1`,`balance`,`member_expire`,`member_type_enum_member_type_enum_id_1`) values (\"3.0\",\"256.8\",\"2026-05-26 10:44:57\",\"3.0\");\nINSERT INTO `28836204`.`wallet` (`user_info_user_info_id_1`,`balance`,`member_expire`,`member_type_enum_member_type_enum_id_1`) values (\"4.0\",\"0.0\",\"2026-05-26 10:44:57\",\"1.0\");\nINSERT INTO `28836204`.`wallet` (`user_info_user_info_id_1`,`balance`,`member_expire`,`member_type_enum_member_type_enum_id_1`) values (\"5.0\",\"1200.75\",\"2026-05-26 10:44:57\",\"3.0\");\n\nCREATE TABLE IF NOT EXISTS `28836204`.`member_type_enum` (\n`member_type_enum_id`