` (`user_info_user_info_id_1`,`create_time`,`content`) values (\"2.0\",\"2024-07-15 13:25:00\",\"实时热力图的刷新能不能再快一点？有时候感觉有延迟。\");\nINSERT INTO `28836204`.`feedback` (`user_info_user_info_id_1`,`create_time`,`content`) values (\"3.0\",\"2024-08-03 17:40:00\",\"厕所导航功能很好用，希望增加更多有免费车位的点位。\");\nINSERT INTO `28836204`.`feedback` (`user_info_user_info_id_1`,`create_time`,`content`) values (\"4.0\",\"2024-08-18 10:10:00\",\"语音播报的声音可以再大一点吗？车里有时候听不清。\");\nINSERT INTO `28836204`.`feedback` (`user_info_user_info_id_1`,`create_time`,`content`) values (\"5.0\",\"2024-09-05 15:55:00\",\"会员权益里的‘热力数据优先展示’具体是什么意思？希望能解释得更清楚。\");\n","backContent":null,"version":1,"dslContent":"","status":"draft"},{"id":254802,"appId":"28836204","requirementId":"1071944423","content":"ALTER TABLE `28836204`.`user_info` ADD COLUMN `password` VARCHAR(255) NULL ; ","backContent":null,"version":1,"dslContent":"{\"description\": \"为支持司机密码登录，user_info表新增password字段，支持注册流程设置密码。\", \"up\": [{\"operation\": \"ALTER_TABLE\", \"table\": \"user_info\", \"action\": {\"type\": \"ADD_COLUMN\", \"column\": {\"name\": \"password\", \"type\": \"password\", \"comment\": \"密码\", \"is_required\": \"0\", \"is_show_list\": \"0\"}}}], \"down\": [{\"operation\": \"ALTER_TABLE\", \"table\": \"user_info\", \"action\": {\"type\": \"DROP_COLUMN\", \"column_name\": \"password\"}}]}","status":"draft"}]}